/* ---------- 男装全类目：分组下拉（诊断台与生成器共用，不做品类映射） ---------- */
const CAT_GROUPS = [
  ['basic',  '上装 · T恤 / 卫衣 / 针织 / 衬衫'],
  ['outer',  '外套 · 夹克 / 风衣 / 棉服 / 马甲'],
  ['pants',  '裤装 · 牛仔 / 长裤 / 短裤'],
  ['formal', '正装 · 西服 / 礼服 / 衬衫'],
  ['sport',  '运动 · 骑行 / 训练 / 泳装'],
  ['utility','连体 · 背带 / 工装'],
  ['home',   '居家 · 睡衣']
];
function catOptionsHTML(cur){
  const q = v => String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  return CAT_GROUPS.map(g=>{
    const items = CATS.filter(c=>c.group===g[0]);
    if(!items.length) return '';
    return '<optgroup label="'+q(g[1])+'">'+items.map(c=>
      '<option value="'+c.id+'"'+(c.id===cur?' selected':'')+'>'+q(c.zh)+'</option>').join('')+'</optgroup>';
  }).join('');
}
function catZhOf(id){ const c=CATS.filter(x=>x.id===id)[0]; return c?c.zh:''; }
function catGroupOf(id){ const c=CATS.filter(x=>x.id===id)[0]; return c?c.group:'basic'; }

