function mkKeyOf(zh, id){
  if(id && SCENE_ID_MK[id]) return SCENE_ID_MK[id];
  var t=String(zh||''), k;
  for(k in SCENE_MK){ if(t.indexOf(k)===0) return SCENE_MK[k]; }
  for(k in SCENE_MK){ if(t.indexOf(k)>-1) return SCENE_MK[k]; }
  return '';
}
