const $ = id => document.getElementById(id);
const byId = (arr,id) => arr.find(x=>x.id===id) || arr[0];
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

function toast(msg){
  const t=$('toast'); t.textContent=msg; t.classList.add('on');
  clearTimeout(window.__tt); window.__tt=setTimeout(()=>t.classList.remove('on'),1700);
}
/* ================= 招商路径复制 ================= */
function copyPath(btn){
  const txt = btn.dataset.path || '';
  const ok = ()=>{
    btn.classList.add('done'); const old=btn.textContent; btn.textContent='已复制';
    setTimeout(()=>{btn.classList.remove('done'); btn.textContent=old;},1400);
    toast('已复制：'+txt);
  };
  const fallback = ()=>{
    const ta=document.createElement('textarea');
    ta.value=txt; ta.style.position='fixed'; ta.style.opacity='0';
    document.body.appendChild(ta); ta.select();
    try{ document.execCommand('copy'); ok(); }catch(e){ toast('复制失败，请手动选择'); }
    document.body.removeChild(ta);
  };
  if(navigator.clipboard && window.isSecureContext){
    navigator.clipboard.writeText(txt).then(ok).catch(fallback);
  } else fallback();
}
/* ================= INIT SELECTS ================= */
function fillSelect(el, arr, valKey, txtFn){
  el.innerHTML = arr.map(x=>`<option value="${x.id}">${txtFn(x)}</option>`).join('');
  el.value = S[valKey];
}
function initStatic(){
  S.imageType=normalizeImageType(S.imageType);
  S.tasks=tasksForImageType(S.imageType);
  fillSelect($('imageType'), IMAGE_TYPES, 'imageType', x=>x.zh);
  $('category').innerHTML = catOptionsHTML(S.category); $('category').value = S.category;
  fillSelect($('tone'), TONES, 'tone', x=>x.zh);
  fillSelect($('modelAge'), AGES, 'age', x=>x.zh);
  fillSelect($('hands'), HANDS, 'hands', x=>x.zh);
  fillSelect($('expr'), EXPRS, 'expr', x=>x.zh);
  S.styling='full';

  renderPoseChips(); renderCropChips();

  $('extra').value = S.extra;

  $('imageType').onchange = e=>{
    S.imageType=e.target.value;
    S.tasks=tasksForImageType(S.imageType);
    render();
  };
  $('category').onchange = e=>{
    S.category=e.target.value;
    if(window.DG && window.DG.syncCategory) window.DG.syncCategory(S.category);
    renderScenes(); render();
  };
  $('tone').onchange = e=>{S.tone=e.target.value; render();};
  $('modelAge').onchange = e=>{S.age=e.target.value; render();};
  $('hands').onchange = e=>{S.hands=e.target.value; render();};
  $('expr').onchange = e=>{S.expr=e.target.value; render();};
  $('cropDetail').value=S.cropDetail;
  $('cropDetail').onchange = e=>{S.cropDetail=e.target.value; render();};
  $('extra').oninput = e=>syncExtraPrompt(e.target.value);
  $('extra').onfocus = ()=>{extraInputFocused=true; renderPromptOutput();};
  $('extra').onblur = ()=>{extraInputFocused=false; renderPromptOutput();};
}

/* ================= REGION / ETH ================= */
function renderRegions(){
  $('regionChips').innerHTML = REGIONS.map(r=>
    `<span class="chip${S.region===r.id?' on':''}" data-rg="${r.id}"><span class="n">${ETH.filter(e=>e.region===r.id).length}</span>${r.zh}</span>`).join('');
  $('regionChips').querySelectorAll('.chip').forEach(c=>{
    c.onclick=()=>{
      S.region=c.dataset.rg;
      const first=ETH.find(e=>e.region===S.region);
      if(first) S.eth=first.id;
      renderRegions(); renderEthGrid(); renderPersona(); render();
    };
  });
  const counts = ETH.filter(e=>e.region===S.region).length;
  $('ethCount').textContent = counts + ' 支';
}
/* ---- hover sample preview ---- */
const LB={open:false};
function openLB(a,b,la,lb2,title,sub){
  if(!a && !b) return;
  hidePV(); LB.open=true;
  const el=$('lb'); $('lbA').src=a||b||''; $('lbB').src=b||a||'';
  $('lbA').alt=la||title||'图片预览'; $('lbB').alt=lb2||title||'图片预览';
  const lrow=el.querySelector('.lb-row'); if(lrow) lrow.classList.toggle('solo', !b);
  $('lbLA').textContent=la||''; $('lbLB').textContent=lb2||'';
  $('lbTitle').textContent=title||''; $('lbSub').textContent=sub||'';
  el.classList.add('on'); el.setAttribute('aria-hidden','false');
  document.body.style.overflow='hidden';
}
function closeLB(){
  const el=$('lb'); if(!el) return;
  el.classList.remove('on'); el.setAttribute('aria-hidden','true');
  el.querySelectorAll('.lb-cell img.zoomed').forEach(img=>img.classList.remove('zoomed'));
  document.body.style.overflow=''; LB.open=false;
}
function openSceneBlank(sceneId){
  const scene=byId(SCENES,sceneId);
  const blank=(window.SCENE_BLANK||{})[scene.id]||'';
  if(!blank){ toast('当前场景暂无独立空白背景图'); return; }
  openLB(blank,'','空白场景图 · 无人物/商品','',scene.zh,'仅展示纯背景、环境与空间布局');
}
function initLB(){
  const el=$('lb'); if(!el) return;
  $('lbX').onclick = e=>{ e.stopPropagation(); closeLB(); };
  el.addEventListener('click', e=>{ if(!e.target.closest('#lbInner')) closeLB(); });
  el.querySelectorAll('.lb-cell img').forEach(img=>{
    img.onclick=()=>img.classList.toggle('zoomed');
  });
  document.addEventListener('keydown', e=>{ if(e.key==='Escape' && LB.open) closeLB(); });
}
const PV={};
function showPV(srcA,srcB,labA,labB,name,meta,anchor){
  if(!srcA && !srcB) { hidePV(); return; }
  if(LB.open) return;
  const el=PV.el||(PV.el=$('pv'));
  PV.ia=PV.ia||$('pvImg'); PV.ib=PV.ib||$('pvImg2');
  PV.la=PV.la||$('pvL1'); PV.lb=PV.lb||$('pvL2');
  PV.nm=PV.nm||$('pvName'); PV.mt=PV.mt||$('pvMeta');
  PV.ia.src=srcA||srcB||''; PV.ib.src=srcB||srcA||'';
  const prow=el.querySelector('.pv-row'); if(prow) prow.classList.toggle('solo', !srcB);
  PV.la.textContent=labA||''; PV.lb.textContent=labB||'';
  PV.nm.textContent=name; PV.mt.textContent=meta;
  const maxW=Math.min(462, window.innerWidth-28);
  el.style.width=maxW+'px';
  el.style.left='-9999px'; el.style.top='-9999px'; el.classList.add('on');
  const w=maxW, h=el.offsetHeight||386, r=anchor.getBoundingClientRect();
  let x=r.right+14;
  if(x+w>window.innerWidth-14) x=r.left-w-14;
  if(x<14) x=Math.max(14,Math.min(window.innerWidth-w-14, r.left));
  let y=Math.max(14, Math.min(r.top+r.height/2-h/2, window.innerHeight-h-14));
  el.style.left=x+'px'; el.style.top=y+'px';
}
function hidePV(){ if(PV.el) PV.el.classList.remove('on'); }

function renderEthGrid(){
  const list = ETH.filter(e=>e.region===S.region);
  if(!list.some(e=>e.id===S.eth)) S.eth = list[0].id;
  $('ethGrid').innerHTML = list.map(e=>
    `<div class="eth-tile${S.eth===e.id?' on':''}" data-eth="${e.id}"><span class="zh">${e.zh}</span><span class="en">${e.en}</span></div>`).join('');
  $('ethGrid').querySelectorAll('.eth-tile').forEach(el=>{
    const e = byId(ETH, el.dataset.eth);
    el.onclick = ()=>{
      S.eth=e.id; renderEthGrid(); renderPersona(); render(); hidePV();
      const plus = S.buildMode==='plus';
      const tk = plus && ETH_IMG[e.id] && ETH_IMG[e.id][S.build] ? S.build : 'T2';
      const tr = TIERS.find(x=>x.id===tk);
      openLB(ETH_IMG[e.id] && ETH_IMG[e.id][tk], ETH_AVG[e.id],
        '大码 ' + (plus && tr ? tr.size : '2XL–3XL'), '常规体型 · 匀称普通型',
        e.zh+' · '+e.en, '人模样张对照');
    };
    el.onmouseenter = ()=>{
      const plus = S.buildMode==='plus';
      const tk = plus && ETH_IMG[e.id] && ETH_IMG[e.id][S.build] ? S.build : 'T2';
      const tr = TIERS.find(x=>x.id===tk);
      showPV(ETH_IMG[e.id] && ETH_IMG[e.id][tk], ETH_AVG[e.id],
        '大码 ' + (plus && tr ? tr.size : '2XL–3XL'), '常规体型 · 匀称普通型',
        e.zh+' · '+e.en, '人模样张对照 · 左大码 / 右常规体型', el);
    };
    el.onmouseleave = hidePV;
  });
}
function renderPersona(){
  const e = byId(ETH,S.eth);
  $('pTitle').textContent = e.zh + ' · ' + e.en;
  $('pRegion').textContent = byId(REGIONS,e.region).zh + ' / ' + e.full;
  const rows = [
    ['规模口径', e.share],
    ['肤色', e.skin],
    ['发型', e.hair],
    ['眼部', e.eyes],
    ['骨相', e.feat],
    ['光位', e.light, 1],
    ['色盘', e.pal, 1],
    ['版型', e.fit, 1]
  ];
  $('pBody').innerHTML = rows.map(([k,v,hi])=>
    `<div class="prow${hi?' hi':''}"><b>${k}</b><div>${esc(v)}</div></div>`).join('');
}


/* ================= 姿势 / 构图：悬停视图 ================= */
const OPT_TIP = {el:null};
function optTipEl(){ return OPT_TIP.el || (OPT_TIP.el = $('optTip')); }
function showTip(anchor, html){
  const el = optTipEl(); if(!el) return;
  el.innerHTML = html;
  el.style.left = '-9999px'; el.style.top = '-9999px';
  el.classList.add('on'); el.setAttribute('aria-hidden','false');
  const r = anchor.getBoundingClientRect(), w = el.offsetWidth || 320, h = el.offsetHeight || 160;
  let x = r.right + 12;
  if(x + w > window.innerWidth - 12) x = Math.max(12, r.left - w - 12);
  let y = Math.max(12, Math.min(r.top + r.height/2 - h/2, window.innerHeight - h - 12));
  el.style.left = x + 'px'; el.style.top = y + 'px';
}
function hideTip(){
  const el = optTipEl(); if(!el) return;
  el.classList.remove('on'); el.setAttribute('aria-hidden','true');
}

/* 真人样张框：band = 入画区间（0–128，对应 3:4 画框） */
/* 当前体型口径：弹窗内看弹窗，生成器看生成器 */
var CUR_BUILD = 'plus';
function poseImgFor(fam){
  var set = (CUR_BUILD === 'plus') ? POSE_IMG_P : POSE_IMG_S;
  return set[fam] || POSE_IMG_P[fam];
}
function cropPhotoBand(key){
  const marks = CROP_PHOTO_LANDMARKS[CUR_BUILD] || CROP_PHOTO_LANDMARKS.regular;
  const bands = {
    pants:[marks.navel,marks.sole],
    top:[marks.nose,marks.thigh],
    longcoat:[marks.nose,marks.sole],
    onepiece:[marks.head,marks.sole],
    full:[marks.head,marks.sole],
    detail:CROP_BANDS.detail
  };
  return bands[key] || CROP_BANDS[key];
}
function sceneBaseImg(zh){
  var base=String(zh||'').split(' · ')[0].trim();
  for(var i=0;i<SCENES.length;i++){
    var b=String(SCENES[i].zh||'').split(' · ')[0].trim();
    if(b===base && SCENE_IMG[SCENES[i].id]) return SCENE_IMG[SCENES[i].id];
  }
  return '';
}
function sceneModelImg(mk){
  if(!mk) return '';
  var set = (CUR_BUILD === 'plus') ? SCENE_MODEL.plus : SCENE_MODEL.std;
  return set[mk] || '';
}
function photoBox(imgSrc, band, tag, cropKey){
  const y0 = Math.max(0, Math.min(128, band[0])), y1 = Math.max(0, Math.min(128, band[1]));
  const top = y0/128*100, h = (y1-y0)/128*100;
  const labels = {
    pants:['肚脐','鞋底'],
    top:['鼻尖','大腿下方'],
    longcoat:['鼻尖','鞋底'],
    onepiece:['头顶','鞋底'],
    full:['头顶','鞋底'],
    detail:['细节上界','细节下界']
  }[cropKey];
  let out = '<div class="ot-photo"><img src="'+imgSrc+'" alt="">';
  if(top > 0.5) out += '<div class="ph-mask" style="height:'+top.toFixed(1)+'%"></div>';
  if(y1 < 127.5) out += '<div class="ph-mask bot" style="height:'+(100-top-h).toFixed(1)+'%"></div>';
  if(top > 0.5) out += '<div class="ph-cut" data-label="'+esc(labels ? labels[0] : '上边界')+'" style="top:'+top.toFixed(1)+'%"></div>';
  if(y1 < 127.5) out += '<div class="ph-cut" data-label="'+esc(labels ? labels[1] : '下边界')+'" style="top:'+(top+h).toFixed(1)+'%"></div>';
  if(tag) out += '<span class="ph-tag">'+esc(tag)+'</span>';
  return out + '</div>';
}
function poseTipHTML(p){
  const seated = (typeof SEATED_POSES!=='undefined') && SEATED_POSES.indexOf(p.id)>-1;
  const bodyKey = CUR_BUILD === 'plus' ? 'plus' : 'regular';
  const bodyLabel = bodyKey === 'plus' ? '大码' : '标码';
  const image = p.images && p.images[bodyKey];
  if(!image || typeof image.dataUrl!=='string') throw new Error('Missing '+bodyKey+' reference image for '+p.refId+'.');
  let h = '<div class="ot-h"><b>'+esc(p.zh)+'</b><i>'+esc(p.refId)+(seated?' · 坐姿':'')+'</i></div>';
  h += '<div class="ot-fig"><div class="ot-photo pose-photo"><img src="'+image.dataUrl+'" alt="'+esc(p.zh)+'姿势示意图"><span class="ph-tag">'+bodyLabel+'示意</span></div>'
     + '<div class="lg"><b>动作参考图</b><br/>图片与下方中英文动作对应，均来自同一姿势数据。</div></div>';
  h += '<div class="ot-r"><b>动作全文</b><span>'+esc(p.desc)+'</span></div>';
  h += '<div class="ot-r"><b>英文原文</b><span>'+esc(p.en)+'</span></div>';
  return h;
}
function cropTipHTML(c){
  const key = c.id;
  const f = FRAMING[key];
  const band = cropPhotoBand(key);
  const bodyLabel = CUR_BUILD === 'plus' ? '大码模特' : '标码模特';
  let h = '<div class="ot-h"><b>'+esc(c.zh)+'</b><i>'+esc(c.en)+'</i></div>';
  h += '<div class="ot-fig">'+photoBox(poseImgFor('stand'), band, FRAME_KEY_CN[key], key)+'<div class="lg"><b>'+bodyLabel+' · 入画范围</b> '+esc(f.zh)
     + '<br/>网纹区＝画外，红线标签标出对应人体边界</div></div>';
  h += '<div class="ot-r"><b>边界</b><span>'+esc(f.zh||'')+'</span></div>';
  if(f.lock) h += '<div class="ot-r hi"><b>锁定条款</b><span>'+esc(f.lock)+'</span></div>';
  if(key==='detail') h += '<div class="ot-r"><b>细节部位</b><span>'+esc(cropDetailText())+'</span></div>';
  return h;
}

function cropDetailText(){
  const labels = {
    auto:'自动识别目标商品最重要的结构细节',
    pocket:'口袋 / 袋盖',
    waistband:'腰头 / 腰带',
    neckline:'领口 / 翻领',
    fabric:'面料 / 纹理',
    placket:'门襟 / 拉链 / 纽扣',
    cuff:'袖口 / 下摆',
    custom:'用户在商品描述中指定的部位'
  };
  return labels[S.cropDetail] || labels.auto;
}

function cropDiagramHTML(c){
  const bounds = CROP_BANDS[c.id];
  const top=bounds[0], bottom=bounds[1];
  return `<svg viewBox="0 0 80 128" role="img" aria-label="${esc(c.zh)}取景边界示意">
    <rect x="1" y="1" width="78" height="126" fill="#f4f1ea" stroke="#ded8cb"/>
    <g fill="none" stroke="#78766f" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
      <circle cx="40" cy="15" r="8" fill="#b9b5aa" stroke="none"/>
      <path d="M34 25h12l5 8-2 27H31l-2-27z" fill="#d0ccc2"/>
      <path d="M31 31 22 51 24 65M49 31 58 51 56 65"/>
      <path d="M34 60 32 91 29 111M46 60 48 91 51 111"/>
      <path d="m29 111-5 3v3h10M51 111l5 3v3H46"/>
    </g>
    <rect x="2" y="2" width="76" height="${top-2}" fill="rgba(244,241,234,.76)"/>
    <rect x="2" y="${bottom}" width="76" height="${126-bottom}" fill="rgba(244,241,234,.76)"/>
    <line x1="2" y1="${top}" x2="78" y2="${top}" stroke="#a8352b" stroke-width="1.7"/>
    <line x1="2" y1="${bottom}" x2="78" y2="${bottom}" stroke="#a8352b" stroke-width="1.7"/>
    ${c.id==='detail'?'<rect x="28" y="43" width="24" height="22" rx="2" fill="none" stroke="#a8352b" stroke-width="1.5" stroke-dasharray="3 2"/>':''}
  </svg>`;
}

function renderPoseChips(){
  const box = $('poseChips'); if(!box) return;
  box.innerHTML = POSES.map(p=>{
    return `<span class="chip pchip${S.stance===p.id?' on':''}" data-p="${p.id}">${esc(p.zh)}</span>`;
  }).join('');
  box.querySelectorAll('.pchip').forEach(el=>{
    const p = byId(POSES, el.dataset.p);
    el.onclick = ()=>{ S.stance = p.id; renderPoseChips(); render(); };
    el.onmouseenter = ()=>{
      showTip(el, poseTipHTML(p));
    };
    el.onmouseleave = hideTip;
  });
}

function renderCropChips(){
  const box = $('cropChips'); if(!box) return;
  const recommended=autoFrameKey();
  const selected=S.crop==='auto' ? recommended : S.crop;
  box.className='crop-options';
  box.innerHTML = CROPS.map(c=>{
    const active=selected===c.id;
    return `<button type="button" class="crop-option${active?' on':''}" data-c="${c.id}" aria-pressed="${active}">
      ${cropDiagramHTML(c)}<span class="crop-option-copy"><b>${esc(c.zh)}</b><span>${esc(c.summary)}</span>${S.crop==='auto'&&recommended===c.id?'<em>品类推荐</em>':''}</span>
    </button>`;
  }).join('');
  box.querySelectorAll('.crop-option').forEach(el=>{
    const c = CROPS.find(x=>x.id===el.dataset.c);
    el.onclick = ()=>{ S.crop = c.id; render(); };
    el.onmouseenter = ()=>{
      showTip(el, cropTipHTML(c));
    };
    el.onmouseleave = hideTip;
  });
  const recommendation=$('cropRecommendation');
  if(recommendation){
    const category=byId(CATS,S.category);
    recommendation.textContent=S.crop==='auto'
      ? `CATEGORY「${category.zh}」推荐：${FRAME_KEY_CN[recommended]}（品类变化时自动更新）`
      : `当前手动选择：${FRAME_KEY_CN[selected]}（品类或其他参数变化不会覆盖）`;
  }
  const detailField=$('cropDetailField');
  if(detailField) detailField.hidden=selected!=='detail';
  const reset=$('cropAutoReset');
  if(reset){
    reset.disabled=S.crop==='auto';
    reset.onclick=()=>{S.crop='auto';render();};
  }
}

/* ================= BUILD ================= */
function renderBuild(){
  $('buildModeChips').querySelectorAll('.chip').forEach(c=>{
    c.classList.toggle('on', c.dataset.bm===S.buildMode);
    c.onclick=()=>{
      S.buildMode=c.dataset.bm;
      S.build = S.buildMode==='plus' ? 'T3' : 'average';
      renderBuild(); render();
    };
  });
  const plus = S.buildMode==='plus';
  $('buildLabel').innerHTML = (plus?'大码档位':'体型特征') + ' <i id="buildNote"></i>';
  const list = plus ? TIERS : NORMAL_BUILDS;
  $('buildChips').innerHTML = list.map(x=>
    `<span class="chip${S.build===x.id?' on':''}" data-b="${x.id}">${x.zh}</span>`).join('');
  $('buildChips').querySelectorAll('.chip').forEach(c=>{
    c.onclick=()=>{S.build=c.dataset.b; renderBuild(); render();};
  });
}

/* ================= SCENES ================= */
function sceneFit(s, cat){
  if(s.id==='dgscene') return 'p';
  if(s.fit){
    if(s.fit.prefer.indexOf(cat.group)>-1) return 'p';
    if(s.fit.ok.indexOf(cat.group)>-1) return 'o';
    return 'n';
  }
  const g = GROUPS[cat.group] || GROUPS.basic;
  if(g.prefer.indexOf(s.id)>-1) return 'p';
  if(g.ok.indexOf(s.id)>-1) return 'o';
  return 'n';
}
function renderScenes(){
  const cat = byId(CATS,S.category);
  const rank = f => f==='p'?0:(f==='o'?1:2);
  const list = SCENES.map(s=>({s:s, f:sceneFit(s,cat)})).sort((a,b)=>rank(a.f)-rank(b.f));
  $('sceneGrid').innerHTML = list.map(({s,f})=>{
    return `<div class="scene${S.scene===s.id?' on':''}" data-sc="${s.id}">
      <div class="scene-copy"><div class="nm">${esc(s.zh)}</div>
      <div class="ds">${esc(s.cat)}</div></div>
      <button type="button" class="scene-blank-btn scene-card-blank" data-scene-blank="${s.id}" aria-label="查看${esc(s.zh)}空白场景图">查看空白场景</button>
    </div>`;
  }).join('');
  /* 下拉框：与网格同源同序 */
  const sel = $('sceneSelect');
  if(sel){
    sel.innerHTML = list.map(({s,f})=>{
      return `<option value="${s.id}">${esc(s.zh)} · ${esc(s.cat||'')}</option>`;
    }).join('');
    sel.value = S.scene;
    sel.onchange = ()=>{ S.scene = sel.value; renderScenes(); render(); hidePV(); };
  }
  const cnt = $('sceneCount');
  if(cnt) cnt.textContent = '';
  $('sceneGrid').querySelectorAll('.scene').forEach((el)=>{
    const s0 = byId(SCENES, el.dataset.sc);
    const b = SCENE_AVG[s0.id] || '';
    const blankButton=el.querySelector('[data-scene-blank]');
    if(blankButton) blankButton.onclick=e=>{
      e.preventDefault();
      e.stopPropagation();
      openSceneBlank(s0.id);
    };
    el.onclick=()=>{
      S.scene=el.dataset.sc; renderScenes(); render(); hidePV();
    };
    el.onmouseenter=()=>{
      const mp = SCENE_MODEL.plus[s0.id], ms = SCENE_MODEL.std[s0.id];
      if(mp && ms) showPV(mp, ms, '大码体型', '标码体型', s0.zh, '场景模特示意 · 仅展示，非实际图片', el);
      else {
        const one = (S.buildMode==='plus') ? mp : ms;
        if(one) showPV(one, '', (S.buildMode==='plus'?'大码体型演示':'标码体型演示'), '', s0.zh, '场景模特示意 · 仅展示，非实际图片', el);
        else if(b) showPV(SCENE_IMG[s0.id], b, '场景照', '常规体型同场景', s0.zh, '场景样图 · 仅展示，非实际图片', el);
        else showPV((window.SCENE_BLANK||{})[s0.id] || SCENE_IMG[s0.id], '', '空景示意 · 无人物', '', s0.zh, '仅展示，非实际图片', el);
      }
    };
    el.onmouseleave=hidePV;
  });
  const onEl = $('sceneGrid').querySelector('.scene.on');
  const scroller = $('sceneScroll');
  if(onEl && scroller && onEl.offsetTop > scroller.scrollTop + scroller.clientHeight - 40){
    scroller.scrollTop = onEl.offsetTop - scroller.clientHeight + 60;
  }
  const s = byId(SCENES,S.scene);
  const fitNow = sceneFit(s, cat);
  const fitTxt = fitNow==='p' ? '● 该品类首选' : (fitNow==='o' ? '○ 该品类可用' : '— 该品类不搭，建议换一个');
  const rows = s.desc
    ? [['场景描述', s.desc], ['适配品类', s.cat], ['匹配度', fitTxt], ['区域适配', s.rg], ['姿势配合', s.sideZh], ['选它的理由', s.why]]
    : [['地点', s.sceneZh], ['背景', s.bgZh], ['承载面', s.floorZh], ['光位', s.lightZh], ['色盘', s.palZh], ['手部', s.sideZh], ['匹配度', fitTxt], ['区域适配', s.rg]];
  $('sceneDetail').innerHTML = `<h4><span>场景档案 · ${esc(s.zh)}</span><span>${esc(s.en||s.cat)}</span></h4>` +
    rows.map(([k,v])=>`<div class="rule-row"><b>${esc(k)}</b><div>${esc(v||'—')}</div></div>`).join('');
}

